// ManifestStop One line on a driver's screen. Note what is absent: no item list, no
// product name, no order total, no vertical. Everything here was snapshotted
// onto the fulfillment when it was created — which is the Fulfillment
// primitive's entire argument, expressed as a response body.
type ManifestStop struct {
	Address *struct {
		Area     *string  `json:"area,omitempty"`
		City     *string  `json:"city,omitempty"`
		Landmark *string  `json:"landmark,omitempty"`
		Lat      *float64 `json:"lat,omitempty"`
		Line     *string  `json:"line,omitempty"`
		Lng      *float64 `json:"lng,omitempty"`
		Notes    *string  `json:"notes,omitempty"`
	} `json:"address,omitempty"`
	AttemptCount *int `json:"attempt_count,omitempty"`

	// CodMinor Cash to collect. Zero for prepaid work.
	CodMinor       *int64              `json:"cod_minor,omitempty"`
	Currency       *string             `json:"currency,omitempty"`
	Eta            *time.Time          `json:"eta,omitempty"`
	FulfillmentId  *openapi_types.UUID `json:"fulfillment_id,omitempty"`
	Kind           *ManifestStopKind   `json:"kind,omitempty"`
	RecipientName  *string             `json:"recipient_name,omitempty"`
	RecipientPhone *string             `json:"recipient_phone,omitempty"`

	// RequiresOtp Sent with the manifest, not discovered at completion. A driver who
	// learns at the door that they needed a code has already walked away.
	RequiresOtp *bool               `json:"requires_otp,omitempty"`
	RouteId     *openapi_types.UUID `json:"route_id,omitempty"`
	Sequence    *int                `json:"sequence,omitempty"`
	Status      *ManifestStopStatus `json:"status,omitempty"`
	Window      *string             `json:"window,omitempty"`
}

